INSERT INTO ntss.sys_data_set (sql_cd, "sql", db_class, detail, can_repeat, use_application, report_class, memo, reg_date, up_date, pre_sql_info) VALUES(
	(select max(sql_cd)+1 from ntss.sys_data_set), 
	'select
	  hosp_pat_id,
	  personal_info_decrypt(pat_last_name)||'''' ''''||personal_info_decrypt(pat_first_name) as pat_name,
	  personal_info_decrypt(pat_last_name_kana)||'''' ''''||personal_info_decrypt(pat_first_name_kana) as pat_name_kana,
	  personal_info_decrypt(pat_last_name_alpha)||'''' ''''||personal_info_decrypt(pat_first_name_alpha) as pat_name_alpha,
	  pat_birthday,
	  case when pat_birthday is null then null
	    else date_part(''''year'''',age(''''now'''', to_date(pat_birthday, ''''YYYYMMDD'''')))
	  end as pat_age,
	  pat_sex,
	  pat_blood_type_abo,
	  pat_blood_type_rh,
	  pat_blood_type_abo * 10 +  pat_blood_type_rh as pat_blood_type_abo_rh,
	  in_out_class,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''zip_cd'''')) as pat_zip,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''address'''')) as pat_address,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''tel1'''')) as pat_tel1,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''tel2'''')) as pat_tel2,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''fax'''')) as pat_fax,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''e_mail'''')) as pat_e_mail,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''work_name'''')) as pat_work_name,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''work_tel'''')) as pat_work_tel,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''memo1'''')) as pat_memo1,
	  trim(both ''''"'''' from personal_info_decrypt(pat_contact_info->>''''memo2'''')) as pat_memo2,
	  severity_cd,
	  transport_cd,
	  is_die,
	  die_date,
	  die_cd
	from
	  pat_personal_main
	where
	  is_del = ''''0''''
	and
	  pat_id = @patId', 3, 
	 '[{"preview": "全員", "can_calc": "", "data_code": "all_staff", "data_name": "全員", "data_type": "string", "conv_table": [], "data_class": "担当者", "field_name": "person_in_charge", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "主治医", "can_calc": "", "data_code": "doctor", "data_name": "主治医", "data_type": "string", "conv_table": [], "data_class": "担当者", "field_name": "person_in_charge", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "担当", "can_calc": "", "data_code": "assume", "data_name": "担当", "data_type": "string", "conv_table": [], "data_class": "担当者", "field_name": "person_in_charge", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "穿刺", "can_calc": "", "data_code": "puncture", "data_name": "穿刺", "data_type": "string", "conv_table": [], "data_class": "担当者", "field_name": "person_in_charge", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "保険", "can_calc": "", "data_code": "insurance", "data_name": "保険", "data_type": "string", "conv_table": [], "data_class": "保険", "field_name": "insurance", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "区分(日付)", "can_calc": "", "data_code": "distinguish", "data_name": "区分(日付)", "data_type": "string", "conv_table": [], "data_class": "入外転入出", "field_name": "turnover", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "病名(有効)", "can_calc": "", "data_code": "disease_name_effective", "data_name": "病名(有効)", "data_type": "string", "conv_table": [], "data_class": "既往歴", "field_name": "medical_history", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "病名(全て)", "can_calc": "", "data_code": "disease_name_all", "data_name": "病名(全て)", "data_type": "string", "conv_table": [], "data_class": "既往歴", "field_name": "medical_history", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "親族", "can_calc": "", "data_code": "relatives", "data_name": "親族", "data_type": "string", "conv_table": [], "data_class": "連絡先", "field_name": "contact_information", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "業者", "can_calc": "", "data_code": "trader", "data_name": "業者", "data_type": "string", "conv_table": [], "data_class": "連絡先", "field_name": "contact_information", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}, {"preview": "加算名", "can_calc": "", "data_code": "additive_name", "data_name": "加算名", "data_type": "string", "conv_table": [], "data_class": "算定加算", "field_name": "calculation_addition", "disp_format": "", "data_category": "患者情報", "facility_table": "", "facility_filter_type": ""}]', '0', '{"applications": [2, 3]}', '{"classes": []}', '患者イベントテキスト項目取得テスト用 @facilityCd @patId @fromDate @toDate', current_timestamp, current_timestamp, NULL);
